('99fff661-9ac9-5803-97eb-1130a3d0da67', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Linguagem de Programação', 'Fácil', 'Fluxos de bytes são adequados para:', '["Somente números decimais em texto.","Somente caracteres ASCII.","Conteúdo binário.","Apenas strings imutáveis.","Exclusivamente arquivos Java."]'::jsonb, 2, 'Fluxos de caracteres tratam texto com semântica de codificação apropriada.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 15, seção 15.2, páginas 543 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4ce31cd7-7105-536c-ac5c-e9cda1e8202f', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Linguagem de Programação', 'Fácil', 'Reader e Writer são abstrações de:', '["Threads.","Entrada e saída de caracteres.","Somente conexões JDBC.","Interfaces gráficas.","Coleções genéricas."]'::jsonb, 1, 'São diferentes das abstrações básicas de fluxo de bytes.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 15, seção 15.2, páginas 543 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('da65e8c0-7209-5f9a-a0ef-98a29a6b19b6', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Linguagem de Programação', 'Fácil', 'Qual interface NIO representa um caminho de arquivo?', '["ResultSet.","Map.","Thread.","JFrame.","Path."]'::jsonb, 4, 'Um caminho não garante que o arquivo correspondente exista.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 15, seção 15.3, páginas 544–546 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d7a09845-2968-5452-972d-5fedf560a910', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Linguagem de Programação', 'Médio', 'Qual classe fornece operações como verificar existência de um caminho?', '["Files.","SystemColor.","Math.","Pattern.","Collections."]'::jsonb, 0, 'Files reúne operações utilitárias do sistema de arquivos.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 15, seção 15.3, páginas 544–546 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ff793e1a-8d89-5bd1-aae5-fd34e5dcca4c', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Linguagem de Programação', 'Médio', 'Criar um objeto Path cria automaticamente o arquivo?', '["Somente se absoluto.","Somente para .txt.","Sim, sempre.","Sim, se o nome for válido.","Não."]'::jsonb, 4, 'Representação de caminho e criação física são operações distintas.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 15, seção 15.3, páginas 544–546 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ec4c6ecb-4a81-54bc-a68e-f75c37536a8c', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Linguagem de Programação', 'Médio', 'Scanner pode ler tokens a partir de:', '["Uma fonte de texto, inclusive arquivo.","Somente bytecode.","Apenas ResultSet.","Somente array de boolean.","Somente teclado."]'::jsonb, 0, 'A API aceita fontes de entrada compatíveis.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 15, seção 15.4, páginas 547–554 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('cde8131b-7855-51c1-8f28-80fcf54d1a4f', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Linguagem de Programação', 'Médio', 'Formatter é usado principalmente para:', '["Sincronizar threads.","Ordenar diretórios.","Desserializar objetos.","Produzir saída textual formatada.","Compilar classes."]'::jsonb, 3, 'A saída pode ser dirigida a destinos suportados.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 15, seção 15.4, páginas 547–554 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f0055fee-5912-5593-9ff4-431f76337814', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Linguagem de Programação', 'Médio', 'Qual cuidado evita perder dados ainda em buffer de saída?', '["Fechar ou descarregar o fluxo adequadamente.","Importar java.lang.","Ordenar o arquivo.","Apenas remover a referência.","Chamar equals."]'::jsonb, 0, 'Flush e fechamento apropriado encaminham conteúdo pendente.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 15, seção 15.4, páginas 547–554 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('dcbe748d-0e66-5098-8f59-8a750f94db21', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Linguagem de Programação', 'Médio', 'Um arquivo de texto inexistente ao tentar abri-lo para leitura pode provocar:', '["Erro de sintaxe.","Uma exceção aritmética.","Conversão em String vazia sempre.","Criação obrigatória com conteúdo padrão.","Uma exceção de entrada/saída apropriada."]'::jsonb, 4, 'O programa precisa tratar falhas de acesso conforme a API usada.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 15, seção 15.4, páginas 547–554 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5f1fd000-2387-5e8c-b6cf-1f5af4b1ea64', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Linguagem de Programação', 'Médio', 'Leitura sequencial significa principalmente:', '["Ler somente números.","Processar os dados na ordem do fluxo.","Eliminar exceções.","Impedir qualquer buffer.","Acessar qualquer registro sem percorrer anteriores por definição."]'::jsonb, 1, 'O fluxo avança durante o consumo das entradas.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 15, seção 15.4, páginas 547–554 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ff35cfd1-ba9d-5f0c-857c-b62930767fc1', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Linguagem de Programação', 'Médio', 'Qual interface marca participação na serialização Java convencional?', '["ActionListener.","Comparable.","Serializable.","Runnable.","AutoCloseable apenas."]'::jsonb, 2, 'Ela não declara métodos a implementar.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 15, seção 15.5, páginas 555–560 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8b93ec8d-4038-5275-8b7b-e85199fafe5c', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Linguagem de Programação', 'Médio', 'ObjectOutputStream é usado para:', '["Executar consultas SQL.","Gravar objetos na forma serializada.","Desenhar imagens.","Compilar objetos.","Somente ler teclas."]'::jsonb, 1, 'A escrita percorre o estado serializável correspondente.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 15, seção 15.5, páginas 555–560 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('2a334f83-4386-525a-b8a9-620975253981', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Linguagem de Programação', 'Médio', 'ObjectInputStream é usado para:', '["Criar arquivos .java.","Executar main.","Enviar eventos Swing.","Ler objetos serializados.","Ordenar mapas."]'::jsonb, 3, 'ReadObject devolve referência que pode exigir verificação ou conversão de tipo.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 15, seção 15.5, páginas 555–560 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f5e7ff77-ffc8-512e-8ff7-7d73287705df', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Linguagem de Programação', 'Médio', 'Um campo transient é, na serialização padrão:', '["Omitido do estado serializado.","Transformado em static.","Sempre convertido em String.","Obrigatoriamente final.","Gravado duas vezes."]'::jsonb, 0, 'Após leitura, seu valor não é recuperado pela serialização padrão daquele campo.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 15, seção 15.5, páginas 555–560 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('bb42181e-de16-513c-a2ac-d15bb0bf5f65', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Linguagem de Programação', 'Médio', 'Campos static compõem o estado de instância serializado pelo mecanismo padrão?', '["Somente se int.","Sim, sempre.","Não.","Somente se public.","Sim, um por objeto."]'::jsonb, 2, 'Campos static pertencem à classe, não a cada instância.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 15, seção 15.5, páginas 555–560 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('154fb53c-447f-50e7-b119-feae15df81e4', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Linguagem de Programação', 'Médio', 'Uma referência não serializável alcançada pela serialização padrão, sem exclusão ou tratamento próprio, pode causar:', '["Compilação automática.","Conversão obrigatória em texto.","ArithmeticException.","NotSerializableException.","Apenas um valor null sem aviso."]'::jsonb, 3, 'O grafo de objetos precisa respeitar os requisitos de serialização.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 15, seção 15.5, páginas 555–560 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('2e827c8a-ddfd-5827-ba42-aa423922b832', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Linguagem de Programação', 'Médio', 'Duas referências compartilhadas ao mesmo objeto podem ser preservadas pela serialização no mesmo fluxo?', '["Somente se todos os campos forem static.","Não, sempre cria cópia independente por referência.","Somente para int.","Não, referências não são serializadas.","Sim, o mecanismo acompanha identidades no grafo."]'::jsonb, 4, 'Serialização não é apenas imprimir cada campo isoladamente.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 15, seção 15.5, páginas 555–560 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('694f60c2-7b3a-5976-a309-785c2e60cb1f', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Linguagem de Programação', 'Médio', 'JFileChooser fornece principalmente:', '["Autorização administrativa.","Serialização obrigatória.","Uma interface de seleção de arquivos.","Compilação dos arquivos.","Leitura automática de todo conteúdo."]'::jsonb, 2, 'Escolher um arquivo é diferente de abri-lo e processar seus dados.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 15, seção 15.6, páginas 561–563 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f04b435c-4d8c-51f3-868d-1414efe9bce1', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Linguagem de Programação', 'Médio', 'BufferedReader acrescenta principalmente:', '["Serialização automática.","Bufferização para leitura de caracteres.","Mudança do sistema de arquivos.","Criptografia obrigatória.","Execução paralela garantida."]'::jsonb, 1, 'O buffer pode reduzir operações de acesso à fonte subjacente.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 15, seção 15.7, páginas 564–565 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('169ec14a-d272-5953-b6c9-a6530dae42ed', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Linguagem de Programação', 'Médio', 'Qual diferença conceitual entre fim do arquivo e falha de leitura?', '["Fim reinicia automaticamente a leitura.","Falha sempre retorna uma linha válida.","Ambos sempre são a mesma IOException.","Fim é condição esperada de término; falha indica problema na operação.","Fim sempre corrompe o arquivo."]'::jsonb, 3, 'A API específica determina como sinaliza essas situações.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 15, seção 15.7, páginas 564–565 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false)
ON CONFLICT (id) DO NOTHING;

COMMIT;
